import { Link,NavLink,Outlet } from 'react-router-dom';import { Moon,Sun,MessageCircle } from 'lucide-react';import { useApp } from '../contexts/appContextValue';const nav=['/','/about','/services','/emi-calculator','/apply','/dashboard','/admin'];export function Layout(){const {dark,toggleDark,lang,setLang}=useApp();return <><header className="sticky top-0 z-50 bg-white/90 backdrop-blur dark:bg-slate-950/90"><div className="container-pad flex h-20 items-center justify-between"><Link to="/" className="text-2xl font-black text-brand-blue dark:text-white">Mahakaya <span className="text-brand-yellow">Enterprise</span></Link><nav className="hidden gap-5 lg:flex">{nav.map(p=><NavLink key={p} to={p} className={({isActive})=>`text-sm font-semibold ${isActive?'text-brand-red':'hover:text-brand-red'}`}>{p==='/'?'Home':p.slice(1).replace('-',' ')}</NavLink>)}</nav><div className="flex items-center gap-2"><select aria-label="Language" className="input py-2" value={lang} onChange={e=>setLang(e.target.value as never)}><option value="en">EN</option><option value="hi">HI</option><option value="bn">BN</option></select><button aria-label="Toggle dark mode" onClick={toggleDark} className="rounded-full border p-3">{dark?<Sun/>:<Moon/>}</button></div></div></header><main><Outlet/></main><a aria-label="WhatsApp" href={`https://wa.me/${import.meta.env.VITE_WHATSAPP_NUMBER||'919876543210'}`} className="fixed bottom-6 right-6 rounded-full bg-green-500 p-4 text-white shadow-premium"><MessageCircle/></a><footer className="bg-brand-blue py-12 text-white"><div className="container-pad grid gap-8 md:grid-cols-3"><div><h2 className="text-2xl font-black">Mahakaya Enterprise</h2><p className="mt-3 text-white/70">Premium financial services for ambitious families and businesses across India.</p></div><div><h3 className="font-bold">Contact</h3><p>+91 98765 43210</p><p>care@mahakayaenterprise.in</p></div><iframe title="Mahakaya office map" className="h-40 w-full rounded-2xl" loading="lazy" src={import.meta.env.VITE_GOOGLE_MAPS_EMBED_URL}/></div></footer></>}
